window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["langchain-chatbot"]=[{"id":"langchain-chatbot-f0001","card":"q-langchain-chatbot-001-1-big-picture","sec":"langchain-chatbot-s002","q":"What is the goal of the LangChain chatbot project, and does it train a model?","a":"<p>A chatbot that answers from your own data (a hotel PDF plus a website) using OpenAI and LangChain, wrapped in a Flask web app. No model is trained. The data is injected through the prompt.</p>","hand":true},{"id":"langchain-chatbot-f0002","card":"q-langchain-chatbot-001-1-big-picture","sec":"langchain-chatbot-s002","q":"What is the pipeline of the LangChain + Flask chatbot, from data to front end?","a":"<p>Extract text, save it to a text file, build a prompt template with that text plus a persona, make a <code>prompt | llm</code> chain, expose it through a Flask route, and call it from an HTML/JS front end.</p>","hand":true},{"id":"langchain-chatbot-f0003","card":"q-langchain-chatbot-001-1-big-picture","sec":"langchain-chatbot-s002","q":"Which technologies make up the LangChain chatbot stack?","a":"<p>Python, the OpenAI API, LangChain, PyMuPDF, requests + BeautifulSoup, Flask, and HTML/CSS/JS.</p>","hand":true},{"id":"langchain-chatbot-f0004","card":"q-langchain-chatbot-001-1-big-picture","sec":"langchain-chatbot-s002","q":"Prompt stuffing vs RAG for feeding your own data to a chatbot: how do they differ?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Approach</th><th>How</th><th>Trade-off</th></tr></thead>\n    <tbody>\n      <tr><td>Prompt stuffing</td><td>Entire extracted text in the prompt</td><td>Simple; fails when data exceeds the context window; pays tokens for all text every call</td></tr>\n      <tr><td>RAG</td><td>Chunk, embed, store in a vector store, retrieve top-k per question</td><td>Scales to large data, cheaper per call; more moving parts</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"langchain-chatbot-f0005","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"What is the only hard requirement for the LangChain chatbot, and where should it be kept?","a":"<p>An <strong>OpenAI API key</strong>, kept in an environment variable or a <code>.env</code> file, never in code.</p>","hand":true},{"id":"langchain-chatbot-f0006","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"How do you set the OpenAI API key as an environment variable on Linux/macOS, on Windows, or in a <code>.env</code> file?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export OPENAI_API_KEY=&quot;your-api-key-here&quot;\n# For Windows\nset OPENAI_API_KEY=your-api-key-here\n# Or use .env file\necho &quot;OPENAI_API_KEY=your-api-key-here&quot; &gt; .env</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0007","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"Which pip packages does the chatbot course install for PDFs, scraping, OpenAI, LangChain and Flask?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pip install PyMuPDF\npip install requests beautifulsoup4\npip install openai\npip install langchain-openai\npip install flask</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0008","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"Besides <code>openai</code>, <code>langchain</code> and <code>langchain-community</code>, which packages does the extended pip install list for the LangChain chatbot add?","a":"<p>PyPDF2, Streamlit and python-dotenv, besides <code>openai</code>, <code>langchain</code>, <code>langchain-community</code>, <code>beautifulsoup4</code>, <code>requests</code> and <code>flask</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pip install openai langchain langchain-community\npip install pypdf2 beautifulsoup4 requests\npip install streamlit flask  # For web interface options\npip install python-dotenv    # For environment variables</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0009","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"How do you load the OpenAI key from a <code>.env</code> file in Python and create a client?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import os\nfrom dotenv import load_dotenv\nload_dotenv()\n\nOPENAI_API_KEY = os.getenv(&quot;OPENAI_API_KEY&quot;)\nos.environ[&quot;OPENAI_API_KEY&quot;] = OPENAI_API_KEY\n\nfrom openai import OpenAI\nclient = OpenAI(api_key=OPENAI_API_KEY)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0010","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"How do you test the OpenAI connection with a tiny request?","a":"<p>Send one short chat completion with <code>max_tokens=10</code> inside try/except and return a success or failure message.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def test_openai_connection():\n    try:\n        response = client.chat.completions.create(\n            model=&quot;gpt-3.5-turbo&quot;,\n            messages=[{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;Hello, test connection&quot;}],\n            max_tokens=10\n        )\n        return &quot;Connection successful&quot;\n    except Exception as e:\n        return f&quot;Connection failed: {str(e)}&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0011","card":"q-langchain-chatbot-002-2-environment-and-api-setup","sec":"langchain-chatbot-s003","q":"What is the lighter way to check that the OpenAI key is available, without calling the API?","a":"<p>Load the environment with <code>load_dotenv()</code> and check that <code>os.getenv(\"OPENAI_API_KEY\")</code> returns a value.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>api_key = os.getenv(&quot;OPENAI_API_KEY&quot;)\nif api_key:\n    print(&quot;OpenAI API Key loaded successfully&quot;)\nelse:\n    print(&quot;ERROR: OpenAI API Key not found&quot;)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0012","card":"q-langchain-chatbot-003-3-1-pdf-extraction","sec":"langchain-chatbot-s004","q":"Which library does the chatbot course use to extract PDF text, and what is the flow?","a":"<p><strong>PyMuPDF</strong> (<code>fitz</code>). Open the file, loop over the pages with <code>load_page</code> and <code>get_text(\"text\")</code>, concatenate the text, close the document and save to a text file.</p>","hand":true},{"id":"langchain-chatbot-f0013","card":"q-langchain-chatbot-003-3-1-pdf-extraction","sec":"langchain-chatbot-s004","q":"How do you extract all text from a PDF with PyMuPDF?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import fitz  # PyMuPDF library\n\ndef extract_text_from_pdf(pdf_file_path):\n    try:\n        doc = fitz.open(pdf_file_path)\n        pdf_text = &quot;&quot;\n        for page_num in range(doc.page_count):\n            page = doc.load_page(page_num)\n            pdf_text += page.get_text(&quot;text&quot;)\n        doc.close()\n        return pdf_text\n    except Exception as e:\n        return f&quot;Error extracting text: {e}&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0014","card":"q-langchain-chatbot-003-3-1-pdf-extraction","sec":"langchain-chatbot-s004","q":"How do you save the extracted PDF text to a file?","a":"<p>Write it with UTF-8 encoding.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pdf_path = &quot;Landon-Hotel.pdf&quot;\nextracted_text = extract_text_from_pdf(pdf_path)\n\nwith open(&quot;pdf_text&quot;, &quot;w&quot;, encoding=&#x27;utf-8&#x27;) as file:\n    file.write(extracted_text)\nprint(&quot;PDF text extraction completed&quot;)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0015","card":"q-langchain-chatbot-003-3-1-pdf-extraction","sec":"langchain-chatbot-s004","q":"What are the alternatives to PyMuPDF for reading a PDF?","a":"<p>PyPDF2 and the LangChain <code>PyPDFLoader</code>.</p>","hand":true},{"id":"langchain-chatbot-f0016","card":"q-langchain-chatbot-003-3-1-pdf-extraction","sec":"langchain-chatbot-s004","q":"How do you extract PDF text with PyPDF2?","a":"<p>Open the file in <code>'rb'</code> mode, create a <code>PdfReader</code>, and join <code>extract_text()</code> of every page.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import PyPDF2\n\ndef extract_text_from_pdf(pdf_path: str) -&gt; str:\n    text = &quot;&quot;\n    with open(pdf_path, &#x27;rb&#x27;) as file:\n        pdf_reader = PyPDF2.PdfReader(file)\n        for page in pdf_reader.pages:\n            text += page.extract_text() + &quot;\\n&quot;\n    return text.strip()</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0017","card":"q-langchain-chatbot-003-3-1-pdf-extraction","sec":"langchain-chatbot-s004","q":"How do you load a PDF with LangChain's <code>PyPDFLoader</code> and combine all pages?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from langchain_community.document_loaders import PyPDFLoader\n\ndef load_pdf_with_langchain(pdf_path: str):\n    loader = PyPDFLoader(pdf_path)\n    documents = loader.load()\n    full_text = &quot;\\n&quot;.join([doc.page_content for doc in documents])\n    return full_text</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0018","card":"q-langchain-chatbot-004-3-2-website-extraction-web-scraping","sec":"langchain-chatbot-s005","q":"What are the steps to extract text from a website with requests and BeautifulSoup?","a":"<p>GET the URL, check for status 200, parse with BeautifulSoup, take the text from <code>&lt;p&gt;</code> tags, and save it to a file. A try/except covers network and parsing errors.</p>","hand":true},{"id":"langchain-chatbot-f0019","card":"q-langchain-chatbot-004-3-2-website-extraction-web-scraping","sec":"langchain-chatbot-s005","q":"How do you scrape the paragraph text of a web page?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>response = requests.get(target_url)\nif response.status_code == 200:\n    soup = BeautifulSoup(response.content, &#x27;html.parser&#x27;)\n    text = &quot;&quot;\n    for paragraph in soup.find_all(&#x27;p&#x27;):\n        text += paragraph.get_text()\n    return text, True\nelse:\n    return f&quot;Error: Status code {response.status_code}&quot;, False</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0020","card":"q-langchain-chatbot-004-3-2-website-extraction-web-scraping","sec":"langchain-chatbot-s005","q":"What does the <code>extract_text_from_website</code> function return, and how is the result used?","a":"<p>A tuple of text and a success flag. On success the text is saved to a file, otherwise the error message is printed.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>extracted_text, success = extract_text_from_website(target_url)\nif success:\n    with open(&#x27;website_text.txt&#x27;, &#x27;w&#x27;) as text_file:\n        text_file.write(extracted_text)\n    print(&quot;Text extracted and saved successfully!&quot;)\nelse:\n    print(extracted_text)  # Print error message</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0021","card":"q-langchain-chatbot-004-3-2-website-extraction-web-scraping","sec":"langchain-chatbot-s005","q":"How does the whole-page scraping variant clean the page before extracting text?","a":"<p>It calls <code>raise_for_status()</code>, removes <code>&lt;script&gt;</code> and <code>&lt;style&gt;</code> elements with <code>decompose()</code>, takes all text, and normalises whitespace.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>response.raise_for_status()\nfor script in soup([&quot;script&quot;, &quot;style&quot;]):\n    script.decompose()\ntext = soup.get_text()\nlines = (line.strip() for line in text.splitlines())\nchunks = (phrase.strip() for line in lines for phrase in line.split(&quot;  &quot;))\ntext = &#x27; &#x27;.join(chunk for chunk in chunks if chunk)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0022","card":"q-langchain-chatbot-004-3-2-website-extraction-web-scraping","sec":"langchain-chatbot-s005","q":"How do you load web pages with LangChain's <code>WebBaseLoader</code>?","a":"<p>Pass a list of URLs, call <code>load()</code> and join the <code>page_content</code> of the documents.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from langchain_community.document_loaders import WebBaseLoader\n\ndef load_website_with_langchain(urls: List[str]):\n    loader = WebBaseLoader(urls)\n    documents = loader.load()\n    combined_text = &quot;\\n&quot;.join([doc.page_content for doc in documents])\n    return combined_text</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0023","card":"q-langchain-chatbot-005-3-3-choosing-a-data-source","sec":"langchain-chatbot-s006","q":"When is a PDF a good data source for a chatbot?","a":"<p>When you need a structured, consistent layout, no network after extraction, and official documents.</p>","hand":true},{"id":"langchain-chatbot-f0024","card":"q-langchain-chatbot-005-3-3-choosing-a-data-source","sec":"langchain-chatbot-s006","q":"When is a website a good data source for a chatbot?","a":"<p>When you need current, dynamic, real-time content.</p>","hand":true},{"id":"langchain-chatbot-f0025","card":"q-langchain-chatbot-005-3-3-choosing-a-data-source","sec":"langchain-chatbot-s006","q":"What is the hybrid data approach?","a":"<p>Combine the PDF and the website.</p>","hand":true},{"id":"langchain-chatbot-f0026","card":"q-langchain-chatbot-005-3-3-choosing-a-data-source","sec":"langchain-chatbot-s006","q":"How does a <code>choose_data_source</code> function decide between PDF and website?","a":"<p>Only a PDF gives <code>\"pdf\"</code>, only a website gives <code>\"website\"</code>. With both, <code>\"structured\"</code> content gives <code>\"pdf\"</code> (better for formatted content) and anything else gives <code>\"website\"</code> (better for current information). With neither it returns <code>\"none\"</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def choose_data_source(has_pdf=False, has_website=False, content_type=&quot;general&quot;):\n    if has_pdf and not has_website:\n        return &quot;pdf&quot;\n    elif has_website and not has_pdf:\n        return &quot;website&quot;\n    elif has_pdf and has_website:\n        if content_type == &quot;structured&quot;:\n            return &quot;pdf&quot;  # Better for formatted content\n        else:\n            return &quot;website&quot;  # Better for current information\n    else:\n        return &quot;none&quot;  # Need at least one source</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0027","card":"q-langchain-chatbot-006-3-4-combined-collector-and-validation","sec":"langchain-chatbot-s007","q":"What does the <code>DataCollector</code> class do, and in which order does it try the inputs?","a":"<p>It collects text from a PDF and from a website. The usage tries the PDF first and falls back to the website.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>collector = DataCollector()\n\nif not collector.collect_pdf_data(&quot;Landon-Hotel.pdf&quot;):\n    collector.collect_website_data(&quot;https://www.landonhotel.com&quot;)\n\nchatbot_data = collector.get_collected_data()</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0028","card":"q-langchain-chatbot-006-3-4-combined-collector-and-validation","sec":"langchain-chatbot-s007","q":"How does <code>collect_pdf_data</code> guard against a missing file or a failed extraction?","a":"<p>It checks <code>os.path.exists(pdf_path)</code> first, wraps the extraction in try/except, saves <code>pdf_text.txt</code> as UTF-8, and returns <code>True</code> or <code>False</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if os.path.exists(pdf_path):\n    try:\n        doc = fitz.open(pdf_path)\n        with open(&quot;pdf_text.txt&quot;, &quot;w&quot;, encoding=&#x27;utf-8&#x27;) as f:\n            f.write(self.pdf_text)\n        return True\n    except Exception as e:\n        print(f&quot;PDF extraction error: {e}&quot;)\n        return False\nelse:\n    print(f&quot;PDF file not found: {pdf_path}&quot;)\n    return False</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0029","card":"q-langchain-chatbot-006-3-4-combined-collector-and-validation","sec":"langchain-chatbot-s007","q":"How does <code>collect_website_data</code> handle a failed HTTP request?","a":"<p>It prints the failed status code and returns <code>False</code>. On status 200 it appends each paragraph's text plus a space and saves <code>website_text.txt</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>response = requests.get(url)\nif response.status_code == 200:\n    for paragraph in soup.find_all(&#x27;p&#x27;):\n        self.website_text += paragraph.get_text() + &quot; &quot;\n    return True\nelse:\n    print(f&quot;Website request failed: {response.status_code}&quot;)\n    return False</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0030","card":"q-langchain-chatbot-006-3-4-combined-collector-and-validation","sec":"langchain-chatbot-s007","q":"What does <code>get_collected_data</code> return?","a":"<p>The PDF text if present, otherwise the website text, otherwise <code>\"No data collected\"</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def get_collected_data(self):\n    if self.pdf_text:\n        return self.pdf_text\n    elif self.website_text:\n        return self.website_text\n    else:\n        return &quot;No data collected&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0031","card":"q-langchain-chatbot-007-3-4-combined-collector-and-validation","sec":"langchain-chatbot-s007","q":"What does <code>validate_extracted_data</code> check and return?","a":"<p>It rejects empty content (<code>\"No content extracted\"</code>) and content shorter than 100 characters (<code>\"Content too short for meaningful chatbot responses\"</code>). Otherwise it strips the text, removes extra whitespace and returns <code>True</code> with the cleaned text.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def validate_extracted_data(text_content):\n    if not text_content or len(text_content.strip()) == 0:\n        return False, &quot;No content extracted&quot;\n    if len(text_content) &lt; 100:\n        return False, &quot;Content too short for meaningful chatbot responses&quot;\n    cleaned_text = text_content.strip()\n    cleaned_text = &#x27; &#x27;.join(cleaned_text.split())  # Remove extra whitespace\n    return True, cleaned_text</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0032","card":"q-langchain-chatbot-007-3-4-combined-collector-and-validation","sec":"langchain-chatbot-s007","q":"How do you validate a saved text file and store the cleaned version?","a":"<p>Read it as UTF-8, call <code>validate_extracted_data</code>, and write the cleaned text to <code>cleaned_data.txt</code> if valid.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>with open(&#x27;pdf_text.txt&#x27;, &#x27;r&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n    raw_text = f.read()\nis_valid, processed_text = validate_extracted_data(raw_text)\nif is_valid:\n    print(&quot;Data validation successful&quot;)\n    with open(&#x27;cleaned_data.txt&#x27;, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n        f.write(processed_text)\nelse:\n    print(f&quot;Data validation failed: {processed_text}&quot;)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0033","card":"q-langchain-chatbot-008-4-calling-openai-directly-vs-through-lan","sec":"langchain-chatbot-s008","q":"How do you call the OpenAI SDK directly to extract keywords from a text?","a":"<p>Use <code>client.chat.completions.create</code> with a <code>system</code> message (the task) and a <code>user</code> message (the input), plus <code>temperature</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from openai import OpenAI\nclient = OpenAI()\n\nresponse = client.chat.completions.create(\n  model=&quot;gpt-3.5-turbo&quot;,\n  messages=[\n    {\n      &quot;role&quot;: &quot;system&quot;,\n      &quot;content&quot;: &quot;You will be provided with a block of text, and your task is to extract a list of keywords from it.&quot;\n    },\n    {\n      &quot;role&quot;: &quot;user&quot;,\n      &quot;content&quot;: &quot;&lt;paragraph of text to extract keywords from&gt;&quot;\n    }\n  ],\n  temperature=0.5\n)\nprint(response.choices[0].message.content)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0034","card":"q-langchain-chatbot-008-4-calling-openai-directly-vs-through-lan","sec":"langchain-chatbot-s008","q":"What roles do the two messages in the direct OpenAI keyword example have?","a":"<p><code>system</code> holds the task and <code>user</code> holds the input.</p>","hand":true},{"id":"langchain-chatbot-f0035","card":"q-langchain-chatbot-008-4-calling-openai-directly-vs-through-lan","sec":"langchain-chatbot-s008","q":"How do you read the answer text from a direct OpenAI chat completion response?","a":"<p><code>response.choices[0].message.content</code></p>","hand":true},{"id":"langchain-chatbot-f0036","card":"q-langchain-chatbot-008-4-calling-openai-directly-vs-through-lan","sec":"langchain-chatbot-s008","q":"How do you initialise LangChain's <code>ChatOpenAI</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from langchain_openai import ChatOpenAI\n\nllm = ChatOpenAI(\n    model=&quot;gpt-3.5-turbo&quot;,\n    temperature=0.7,\n    max_tokens=1000\n)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0037","card":"q-langchain-chatbot-008-4-calling-openai-directly-vs-through-lan","sec":"langchain-chatbot-s008","q":"How does LangChain send a conversation to the model, and what do you read from the result?","a":"<p>Build a list of <code>SystemMessage</code> and <code>HumanMessage</code>, call <code>llm.invoke(messages)</code> and read <code>response.content</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from langchain.schema import HumanMessage, SystemMessage\n\ndef basic_chat(user_message: str) -&gt; str:\n    messages = [\n        SystemMessage(content=&quot;You are a helpful assistant.&quot;),\n        HumanMessage(content=user_message)\n    ]\n    response = llm.invoke(messages)\n    return response.content</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0038","card":"q-langchain-chatbot-008-4-calling-openai-directly-vs-through-lan","sec":"langchain-chatbot-s008","q":"Which LangChain model class does the course chatbot itself use, and which one is it not?","a":"<p>The completion-style <code>OpenAI</code> class (<code>gpt-3.5-turbo-instruct</code>), not <code>ChatOpenAI</code>.</p>","hand":true},{"id":"langchain-chatbot-f0039","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"What is the idea of the persona prompt in the course chatbot?","a":"<p>Put the extracted text and an instruction block into one prompt, so the model answers only from that text and refuses everything else.</p>","hand":true},{"id":"langchain-chatbot-f0040","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"What is the persona of the course chatbot, and why use one?","a":"<p>\"Mr. Landon\", the hotel manager, to keep a consistent voice.</p>","hand":true},{"id":"langchain-chatbot-f0041","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"How does the chatbot limit its scope?","a":"<p>With a fixed refusal, \"I can't assist you with that, sorry!\", for questions that are not about Landon Hotel.</p>","hand":true},{"id":"langchain-chatbot-f0042","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"What does <code>{question}</code> do in the chatbot prompt?","a":"<p>It is the placeholder declared with <code>PromptTemplate(input_variables=[\"question\"])</code>.</p>","hand":true},{"id":"langchain-chatbot-f0043","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"Why does the chatbot use <code>temperature=0</code>?","a":"<p>It makes the answers deterministic and factual.</p>","hand":true},{"id":"langchain-chatbot-f0044","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"What does <code>prompt_template | llm</code> build, and how do you run it?","a":"<p>The pipe operator (LCEL) builds a chain. Run it with <code>.invoke({...})</code>.</p>","hand":true},{"id":"langchain-chatbot-f0045","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"How do you build the persona prompt template from the extracted text?","a":"<p>Read the text file, append the instruction block with <code>Question: {question}</code> and <code>Answer:</code>, and wrap it in a <code>PromptTemplate</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from langchain_openai import OpenAI\nfrom langchain.prompts import PromptTemplate\n\nprompt = open(&#x27;website_text.txt&#x27;, &#x27;r&#x27;).read()\n\nhotel_assistant_prompt_template = PromptTemplate(\n    input_variables=[&quot;question&quot;],\n    template=hotel_assistant_template\n)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0046","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"How do you create the LLM and the chain of the persona chatbot?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>llm = OpenAI(model=&#x27;gpt-3.5-turbo-instruct&#x27;, temperature=0)\n\nllm_chain = hotel_assistant_prompt_template | llm</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0047","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"How do you wrap the chain in a function and test the chatbot from the command line?","a":"<p><code>query_llm</code> returns the chain's answer. A loop reads <code>input()</code> and stops on <code>quit</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def query_llm(question):\n    response = llm_chain.invoke({&#x27;question&#x27;: question})\n    return response\n\ndef test_chatbot():\n    print(&quot;Landon Hotel Chatbot - Type &#x27;quit&#x27; to exit&quot;)\n    while True:\n        user_input = input(&quot;You: &quot;)\n        if user_input.lower() == &#x27;quit&#x27;:\n            break\n        response = query_llm(user_input)\n        print(f&quot;Mr. Landon: {response}&quot;)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0048","card":"q-langchain-chatbot-009-5-the-course-chatbot-persona-prompt-lang","sec":"langchain-chatbot-s009","q":"What answers should the persona chatbot give for hotel questions and for \"What is LangChain?\"","a":"<p>Greetings and hotel questions (name, location in London's West End, check-in at 3:00 PM, amenities) are answered from the data. \"What is LangChain?\", \"What is OpenAI?\" and \"Tell me about Python\" return the refusal.</p>","hand":true},{"id":"langchain-chatbot-f0049","card":"q-langchain-chatbot-010-6-1-changes-from-the-cli-version","sec":"langchain-chatbot-s010","q":"What changes when the command-line chatbot becomes a Flask app?","a":"<p><code>query_llm</code> returns the response instead of printing it, and the <code>while True</code> loop is gone.</p>","hand":true},{"id":"langchain-chatbot-f0050","card":"q-langchain-chatbot-010-6-1-changes-from-the-cli-version","sec":"langchain-chatbot-s010","q":"Which routes does the Flask chatbot have and what do they do?","a":"<p><code>/</code> serves the page. <code>/chatbot</code> (POST) takes <code>{\"question\": ...}</code> and returns <code>{\"response\": ...}</code>.</p>","hand":true},{"id":"langchain-chatbot-f0051","card":"q-langchain-chatbot-010-6-1-changes-from-the-cli-version","sec":"langchain-chatbot-s010","q":"What is <code>debug=True</code> in Flask for?","a":"<p>Development only.</p>","hand":true},{"id":"langchain-chatbot-f0052","card":"q-langchain-chatbot-010-6-1-changes-from-the-cli-version","sec":"langchain-chatbot-s010","q":"How do you write the Flask app with the page route and the chatbot route?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from flask import Flask, render_template, request, jsonify\n\napp = Flask(__name__)\n\n@app.route(&quot;/&quot;)\ndef index():\n    return render_template(&quot;index.html&quot;)\n\n@app.route(&quot;/chatbot&quot;, methods=[&quot;POST&quot;])\ndef chatbot():\n    data = request.get_json()\n    question = data[&quot;question&quot;]\n    response = query_llm(question)\n    return jsonify({&quot;response&quot;: response})\n\nif __name__ == &quot;__main__&quot;:\n    app.run(debug=True)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0053","card":"q-langchain-chatbot-010-6-1-changes-from-the-cli-version","sec":"langchain-chatbot-s010","q":"Where must the HTML template of a Flask app live?","a":"<p>In a folder named exactly <code>templates</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>project/\n├── main.py (Flask application)\n├── website_text.txt (extracted content)\n└── templates/\n    └── index.html (must be in templates folder)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0054","card":"q-langchain-chatbot-011-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"What is the JavaScript flow of the chat page?","a":"<p><code>sendMessage</code> trims the input, shows it, posts it and clears the box. <code>displayMessage</code> appends a div and auto-scrolls. <code>sendMessageToServer</code> does <code>fetch('/chatbot')</code> and shows <code>data.response</code>.</p>","hand":true},{"id":"langchain-chatbot-f0055","card":"q-langchain-chatbot-011-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"Which HTML elements make up the basic chatbot page?","a":"<p>A heading, a <code>chat-container</code> div, a text input with id <code>user-input</code> and a button with id <code>send-btn</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;h1&gt;Landon Hotel Chatbot&lt;/h1&gt;\n&lt;div id=&quot;chat-container&quot;&gt;&lt;/div&gt;\n&lt;input type=&quot;text&quot; id=&quot;user-input&quot; placeholder=&quot;Type your message...&quot; /&gt;\n&lt;button id=&quot;send-btn&quot;&gt;Send&lt;/button&gt;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0056","card":"q-langchain-chatbot-011-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"How does the page style the chat window and the user and bot messages?","a":"<p>The container is 400x500 px with a scrollbar. User messages are bold blue and bot messages are bold green.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>#chat-container {\n    width: 400px;\n    height: 500px;\n    border: 1px solid #ccc;\n    overflow-y: scroll;\n    padding: 10px;\n}\n.user {\n    font-weight: bold;\n    color: blue;\n}\n.bot {\n    font-weight: bold;\n    color: green;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0057","card":"q-langchain-chatbot-011-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"How does the page connect the Send button to the JavaScript code?","a":"<p>It grabs the DOM elements and registers a click listener.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const chatContainer = document.getElementById(&#x27;chat-container&#x27;);\nconst userInput = document.getElementById(&#x27;user-input&#x27;);\nconst sendBtn = document.getElementById(&#x27;send-btn&#x27;);\n\nsendBtn.addEventListener(&#x27;click&#x27;, sendMessage);</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0058","card":"q-langchain-chatbot-012-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"What does <code>sendMessage</code> do in the chat page?","a":"<p>It reads and trims the input. If it is not empty, it displays the user message, sends it to the server and clears the input.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>function sendMessage() {\n    const userMessage = userInput.value.trim();\n    if (userMessage) {\n        displayMessage(&#x27;user&#x27;, userMessage);\n        sendMessageToServer(userMessage);\n        userInput.value = &#x27;&#x27;;\n    }\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0059","card":"q-langchain-chatbot-012-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"What does <code>displayMessage</code> do?","a":"<p>It creates a div with the classes <code>message</code> and the sender, sets its text, appends it to the chat container and scrolls to the bottom.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>function displayMessage(sender, message) {\n    const messageElement = document.createElement(&#x27;div&#x27;);\n    messageElement.classList.add(&#x27;message&#x27;);\n    messageElement.classList.add(sender);\n    messageElement.textContent = `${sender}: ${message}`;\n    chatContainer.appendChild(messageElement);\n    chatContainer.scrollTop = chatContainer.scrollHeight;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0060","card":"q-langchain-chatbot-012-6-2-html-javascript-template-templates-i","sec":"langchain-chatbot-s011","q":"How does the page post the question to the Flask backend?","a":"<p>With <code>fetch('/chatbot')</code> using POST, a JSON content type and the body <code>{question: message}</code>. It shows <code>data.response</code> as the bot message.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>fetch(&#x27;/chatbot&#x27;, {\n    method: &#x27;POST&#x27;,\n    headers: {\n        &#x27;Content-Type&#x27;: &#x27;application/json&#x27;,\n    },\n    body: JSON.stringify({ question: message }),\n})\n.then((response) =&gt; response.json())\n.then((data) =&gt; {\n    displayMessage(&#x27;bot&#x27;, data.response);\n})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0061","card":"q-langchain-chatbot-013-6-3-running","sec":"langchain-chatbot-s012","q":"How do you start the Flask chatbot and where is it available?","a":"<p>Run <code>python main.py</code>. The app is available at <code>http://localhost:5000</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>python main.py</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0062","card":"q-langchain-chatbot-013-6-3-running","sec":"langchain-chatbot-s012","q":"What is the request path of a question in the Flask chatbot?","a":"<p>Browser, <code>fetch</code>, Flask <code>/chatbot</code>, LangChain chain, OpenAI, JSON, page.</p>","hand":true},{"id":"langchain-chatbot-f0063","card":"q-langchain-chatbot-014-7-testing-and-troubleshooting","sec":"langchain-chatbot-s013","q":"What should you test on the Landon chatbot?","a":"<p>Both valid hotel questions and out-of-scope questions. The refusal must trigger for the out-of-scope ones.</p>","hand":true},{"id":"langchain-chatbot-f0064","card":"q-langchain-chatbot-014-7-testing-and-troubleshooting","sec":"langchain-chatbot-s013","q":"Which test cases does the course use for the chatbot, and what should each return?","a":"<p>Hotel questions: \"Hi\" greets and introduces Mr. Landon, \"Where is the hotel?\" mentions London West End, \"What time is check-in?\" says 3:00 PM, \"What are the amenities?\" lists facilities. Non-hotel questions (\"What is Python?\", \"Tell me about AI\", \"What's the weather?\") should say it can't assist.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>test_cases = [\n    (&quot;Hi&quot;, &quot;should greet and introduce Mr. Landon&quot;),\n    (&quot;Where is the hotel?&quot;, &quot;should mention London West End&quot;),\n    (&quot;What time is check-in?&quot;, &quot;should say 3:00 PM&quot;),\n    (&quot;What are the amenities?&quot;, &quot;should list hotel facilities&quot;),\n    (&quot;What is Python?&quot;, &quot;should say can&#x27;t assist&quot;),\n    (&quot;Tell me about AI&quot;, &quot;should say can&#x27;t assist&quot;),\n    (&quot;What&#x27;s the weather?&quot;, &quot;should say can&#x27;t assist&quot;)\n]</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0065","card":"q-langchain-chatbot-014-7-testing-and-troubleshooting","sec":"langchain-chatbot-s013","q":"Which files must exist before running the Flask chatbot?","a":"<p><code>main.py</code>, <code>website_text.txt</code> (or <code>pdf_text.txt</code>) and <code>templates/index.html</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>required_files = [\n    &quot;main.py&quot;,\n    &quot;website_text.txt&quot;,  # or pdf_text.txt\n    &quot;templates/index.html&quot;\n]</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0066","card":"q-langchain-chatbot-014-7-testing-and-troubleshooting","sec":"langchain-chatbot-s013","q":"Which template locations work or fail in Flask?","a":"<p><code>templates/index.html</code> is correct. <code>index.html</code> in the root directory and <code>template/index.html</code> (wrong folder name) are incorrect. Flask automatically looks in the <code>templates</code> folder.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># CORRECT: templates/index.html\n# INCORRECT: index.html (in root directory)\n# INCORRECT: template/index.html (wrong folder name)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0067","card":"q-langchain-chatbot-014-7-testing-and-troubleshooting","sec":"langchain-chatbot-s013","q":"How do you detect a missing OpenAI key at start-up?","a":"<p>Check <code>os.getenv(\"OPENAI_API_KEY\")</code> and print an error with the export command if it is empty.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if not os.getenv(&quot;OPENAI_API_KEY&quot;):\n    print(&quot;ERROR: OpenAI API key not found&quot;)\n    print(&quot;Set it with: export OPENAI_API_KEY=&#x27;your-key-here&#x27;&quot;)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0068","card":"q-langchain-chatbot-015-8-rag-upgrade-chunking-vector-store-retr","sec":"langchain-chatbot-s014","q":"When do you upgrade the chatbot from prompt stuffing to RAG, and what is the flow?","a":"<p>When the data is too big for the prompt. Load, split into overlapping chunks, embed, store in FAISS, retrieve the top-k similar chunks per question, and let the LLM answer from them.</p>","hand":true},{"id":"langchain-chatbot-f0069","card":"q-langchain-chatbot-015-8-rag-upgrade-chunking-vector-store-retr","sec":"langchain-chatbot-s014","q":"What do <code>chunk_size=1000</code> and <code>chunk_overlap=200</code> mean in <code>RecursiveCharacterTextSplitter</code>?","a":"<p>Chunks are 1000 characters long, and consecutive chunks overlap by 200. The overlap preserves context across chunk edges.</p>","hand":true},{"id":"langchain-chatbot-f0070","card":"q-langchain-chatbot-015-8-rag-upgrade-chunking-vector-store-retr","sec":"langchain-chatbot-s014","q":"What do <code>OpenAIEmbeddings</code> and <code>as_retriever(search_kwargs={\"k\": 3})</code> do?","a":"<p><code>OpenAIEmbeddings</code> turns text into vectors. <code>as_retriever(search_kwargs={\"k\": 3})</code> returns the top 3 chunks.</p>","hand":true},{"id":"langchain-chatbot-f0071","card":"q-langchain-chatbot-015-8-rag-upgrade-chunking-vector-store-retr","sec":"langchain-chatbot-s014","q":"What does <code>chain_type=\"stuff\"</code> do in a RAG chain?","a":"<p>It puts all retrieved chunks into one prompt.</p>","hand":true},{"id":"langchain-chatbot-f0072","card":"q-langchain-chatbot-015-8-rag-upgrade-chunking-vector-store-retr","sec":"langchain-chatbot-s014","q":"What is <code>ConversationBufferMemory</code> used for?","a":"<p>It keeps the chat history so follow-up questions work.</p>","hand":true},{"id":"langchain-chatbot-f0073","card":"q-langchain-chatbot-016-8-1-document-processing-pipeline","sec":"langchain-chatbot-s015","q":"How does the <code>DocumentProcessor</code> set up chunking and embeddings?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from langchain.text_splitter import RecursiveCharacterTextSplitter\nfrom langchain.embeddings import OpenAIEmbeddings\nfrom langchain.vectorstores import FAISS\n\nclass DocumentProcessor:\n    def __init__(self):\n        self.text_splitter = RecursiveCharacterTextSplitter(\n            chunk_size=1000,\n            chunk_overlap=200\n        )\n        self.embeddings = OpenAIEmbeddings()</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0074","card":"q-langchain-chatbot-016-8-1-document-processing-pipeline","sec":"langchain-chatbot-s015","q":"How does <code>process_documents</code> turn a list of texts into a FAISS vector store?","a":"<p>It splits every text into chunks, collects all the chunks, and builds the store with <code>FAISS.from_texts</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>chunks = []\nfor text in texts:\n    text_chunks = self.text_splitter.split_text(text)\n    chunks.extend(text_chunks)\nvectorstore = FAISS.from_texts(chunks, self.embeddings)\nreturn vectorstore</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0075","card":"q-langchain-chatbot-016-8-1-document-processing-pipeline","sec":"langchain-chatbot-s015","q":"How do you create a retriever for similarity search from a vector store?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def create_retriever(self, vectorstore):\n    return vectorstore.as_retriever(search_kwargs={&quot;k&quot;: 3})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0076","card":"q-langchain-chatbot-016-8-1-document-processing-pipeline","sec":"langchain-chatbot-s015","q":"How do you use the <code>DocumentProcessor</code> on the PDF and website text?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>processor = DocumentProcessor()\ndocuments = [pdf_text, website_text]  # From previous examples\nvectorstore = processor.process_documents(documents)\nretriever = processor.create_retriever(vectorstore)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0077","card":"q-langchain-chatbot-017-8-2-rag-chatbot-retrievalqa-with-a-custo","sec":"langchain-chatbot-s016","q":"How does the RAG chatbot build its <code>RetrievalQA</code> chain with a custom prompt?","a":"<p>It makes a <code>PromptTemplate</code> with the <code>context</code> and <code>question</code> variables and passes it through <code>chain_type_kwargs</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>prompt = PromptTemplate(\n    template=prompt_template,\n    input_variables=[&quot;context&quot;, &quot;question&quot;]\n)\nself.qa_chain = RetrievalQA.from_chain_type(\n    llm=self.llm,\n    chain_type=&quot;stuff&quot;,\n    retriever=self.retriever,\n    return_source_documents=True,\n    chain_type_kwargs={&quot;prompt&quot;: prompt}\n)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0078","card":"q-langchain-chatbot-017-8-2-rag-chatbot-retrievalqa-with-a-custo","sec":"langchain-chatbot-s016","q":"What does the custom RAG prompt tell the model to do?","a":"<p>To answer using the given context, and to say so if it does not know the answer from the context.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Context: {context}\nQuestion: {question}\nAnswer:</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0079","card":"q-langchain-chatbot-017-8-2-rag-chatbot-retrievalqa-with-a-custo","sec":"langchain-chatbot-s016","q":"What does <code>return_source_documents=True</code> do in <code>RetrievalQA</code>?","a":"<p>The result also holds the retrieved documents, so the chatbot can show which chunks were used.</p>","hand":true},{"id":"langchain-chatbot-f0080","card":"q-langchain-chatbot-017-8-2-rag-chatbot-retrievalqa-with-a-custo","sec":"langchain-chatbot-s016","q":"How do you call the RetrievalQA chain and read the answer?","a":"<p>Invoke it with the key <code>query</code> and read <code>result[\"result\"]</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>result = self.qa_chain.invoke({&quot;query&quot;: question})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0081","card":"q-langchain-chatbot-017-8-2-rag-chatbot-retrievalqa-with-a-custo","sec":"langchain-chatbot-s016","q":"What does the RAG chatbot's <code>chat</code> method return on success and on failure?","a":"<p>A dict with <code>answer</code>, the first 200 characters of each retrieved chunk plus <code>...</code>, and <code>success</code>. On an exception it returns an error message, an empty list and <code>success: False</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>return {\n    &quot;answer&quot;: result[&quot;result&quot;],\n    &quot;success&quot;: True\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0082","card":"q-langchain-chatbot-017-8-2-rag-chatbot-retrievalqa-with-a-custo","sec":"langchain-chatbot-s016","q":"How do you create and test the RAG chatbot?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>chatbot = PersonalizedChatbot(retriever, llm)\n\nresponse = chatbot.chat(&quot;What is the main topic of the documents?&quot;)\nprint(f&quot;Answer: {response[&#x27;answer&#x27;]}&quot;)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0083","card":"q-langchain-chatbot-018-8-3-conversation-memory-conversationalre","sec":"langchain-chatbot-s017","q":"How do you add conversation memory to the RAG chatbot?","a":"<p>Create a <code>ConversationBufferMemory</code> with <code>memory_key=\"chat_history\"</code> and <code>return_messages=True</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>self.memory = ConversationBufferMemory(\n    memory_key=&quot;chat_history&quot;,\n    return_messages=True\n)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0084","card":"q-langchain-chatbot-018-8-3-conversation-memory-conversationalre","sec":"langchain-chatbot-s017","q":"How do you build a <code>ConversationalRetrievalChain</code>?","a":"<p>Use <code>from_llm</code> with the LLM, the retriever, the memory and <code>return_source_documents=True</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>self.conversation_chain = ConversationalRetrievalChain.from_llm(\n    llm=self.llm,\n    retriever=self.retriever,\n    memory=self.memory,\n    return_source_documents=True\n)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0085","card":"q-langchain-chatbot-018-8-3-conversation-memory-conversationalre","sec":"langchain-chatbot-s017","q":"What key does <code>ConversationalRetrievalChain</code> take as input and which key holds the answer?","a":"<p>The input key is <code>question</code> and the answer is in <code>result[\"answer\"]</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>result = self.conversation_chain.invoke({&quot;question&quot;: question})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0086","card":"q-langchain-chatbot-018-8-3-conversation-memory-conversationalre","sec":"langchain-chatbot-s017","q":"How do you reset the conversation history of the memory chatbot?","a":"<p>Call <code>self.memory.clear()</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def clear_memory(self):\n    self.memory.clear()</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0087","card":"q-langchain-chatbot-018-8-3-conversation-memory-conversationalre","sec":"langchain-chatbot-s017","q":"How do you show that the conversational bot uses context from earlier questions?","a":"<p>Ask a follow-up such as \"Can you elaborate on that?\" on the same bot object.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>conversational_bot = ConversationalChatbot(retriever, llm)\nresponse1 = conversational_bot.chat(&quot;What is the document about?&quot;)\nresponse2 = conversational_bot.chat(&quot;Can you elaborate on that?&quot;)  # Uses context</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0088","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"What do the Streamlit and Flask API interfaces wrap, and how do they differ?","a":"<p>Both wrap <code>conversational_bot</code>. Streamlit keeps it in <code>st.session_state</code>. The Flask API adds <code>/chat</code>, <code>/clear</code>, <code>/health</code> and CORS.</p>","hand":true},{"id":"langchain-chatbot-f0089","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"How does the Streamlit app keep the chatbot between interactions?","a":"<p>It stores it in <code>st.session_state</code> on first run.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if &#x27;chatbot&#x27; not in st.session_state:\n    st.session_state.chatbot = conversational_bot</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0090","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"How does the Streamlit app handle a question and show a waiting state?","a":"<p>It reads a text input, and on the <code>Ask</code> button it calls the chatbot inside <code>st.spinner(\"Thinking...\")</code> and writes the answer.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>user_question = st.text_input(&quot;Your question:&quot;)\nif st.button(&quot;Ask&quot;):\n    if user_question:\n        with st.spinner(&quot;Thinking...&quot;):\n            response = st.session_state.chatbot.chat(user_question)\n        st.write(&quot;**Answer:**&quot;)\n        st.write(response[&quot;answer&quot;])</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0091","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"How does the Streamlit app clear the conversation, and how do you run it?","a":"<p>A <code>Clear Conversation</code> button calls <code>clear_memory()</code>. Run it with <code>streamlit run app.py</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if st.button(&quot;Clear Conversation&quot;):\n    st.session_state.chatbot.clear_memory()\n    st.success(&quot;Conversation cleared!&quot;)\n\n# Run with: streamlit run app.py</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0092","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"How do you enable CORS in the Flask chatbot API?","a":"<p>Use <code>flask_cors</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from flask_cors import CORS\n\napp = Flask(__name__)\nCORS(app)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0093","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"What does the <code>/chat</code> endpoint of the Flask API do on a missing question or an error?","a":"<p>It returns <code>{\"error\": \"No question provided\"}</code> with status 400 if the question is empty, and the error text with status 500 on an exception.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@app.route(&#x27;/chat&#x27;, methods=[&#x27;POST&#x27;])\ndef chat_endpoint():\n    try:\n        data = request.get_json()\n        question = data.get(&#x27;question&#x27;, &#x27;&#x27;)\n        if not question:\n            return jsonify({&quot;error&quot;: &quot;No question provided&quot;}), 400\n        response = global_chatbot.chat(question)\n    except Exception as e:\n        return jsonify({&quot;error&quot;: str(e)}), 500</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0094","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"What do the <code>/clear</code> and <code>/health</code> endpoints do?","a":"<p><code>/clear</code> (POST) clears the conversation memory and returns <code>{\"message\": \"Memory cleared\"}</code>. <code>/health</code> (GET) returns <code>{\"status\": \"healthy\"}</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@app.route(&#x27;/clear&#x27;, methods=[&#x27;POST&#x27;])\ndef clear_memory():\n    global_chatbot.clear_memory()\n    return jsonify({&quot;message&quot;: &quot;Memory cleared&quot;})\n\n@app.route(&#x27;/health&#x27;, methods=[&#x27;GET&#x27;])\ndef health_check():\n    return jsonify({&quot;status&quot;: &quot;healthy&quot;})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0095","card":"q-langchain-chatbot-019-9-alternative-interfaces-streamlit-and-a","sec":"langchain-chatbot-s018","q":"How do you run the Flask chatbot API (host and port)?","a":"<p>Run <code>python app.py</code> with <code>app.run(debug=True, host='0.0.0.0', port=5000)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>app.run(debug=True, host=&#x27;0.0.0.0&#x27;, port=5000)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0096","card":"q-langchain-chatbot-020-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"How does the modern chatbot page style the body and the chat container?","a":"<p>The body has a diagonal gradient background and the container is at most 800px wide, centred, white, with rounded corners and a shadow.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>body {\n    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n    margin: 0;\n    padding: 20px;\n    min-height: 100vh;\n}\n.chatbot-container {\n    max-width: 800px;\n    margin: 0 auto;\n    background: white;\n    border-radius: 15px;\n    box-shadow: 0 10px 30px rgba(0,0,0,0.2);\n    overflow: hidden;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0097","card":"q-langchain-chatbot-020-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"How are the chat header and the message area styled?","a":"<p>The header is dark grey with white centred text. The message area is 500px high and scrolls vertically.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>.chat-header {\n    background: #4a5568;\n    color: white;\n    padding: 20px;\n    text-align: center;\n}\n#chat-container {\n    height: 500px;\n    overflow-y: auto;\n    padding: 20px;\n    background: #f7fafc;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0098","card":"q-langchain-chatbot-020-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"How are the message bubbles styled for user and bot?","a":"<p>Messages have rounded bubbles up to 70% wide. User messages are blue, right-aligned (<code>margin-left: auto</code>). Bot messages are green and left-aligned (<code>margin-right: auto</code>).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>.message {\n    margin-bottom: 15px;\n    padding: 12px 16px;\n    border-radius: 18px;\n    max-width: 70%;\n    word-wrap: break-word;\n}\n.user {\n    background: #4299e1;\n    color: white;\n    margin-left: auto;\n    text-align: right;\n}\n.bot {\n    background: #48bb78;\n    color: white;\n    margin-right: auto;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0099","card":"q-langchain-chatbot-020-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"How is the input row styled in the modern chat page?","a":"<p>A flex container with a top border. The input grows (<code>flex: 1</code>) with rounded corners (25px) and no outline.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>.input-container {\n    display: flex;\n    padding: 20px;\n    background: white;\n    border-top: 1px solid #e2e8f0;\n}\n#user-input {\n    flex: 1;\n    padding: 12px 16px;\n    border: 2px solid #e2e8f0;\n    border-radius: 25px;\n    outline: none;\n    font-size: 16px;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0100","card":"q-langchain-chatbot-021-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"How is the Send button styled and how does it react to hover?","a":"<p>A blue pill button with a 0.3s background transition. On hover the background becomes a darker blue.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>#send-btn {\n    margin-left: 10px;\n    padding: 12px 24px;\n    background: #4299e1;\n    color: white;\n    border: none;\n    border-radius: 25px;\n    font-size: 16px;\n    transition: background 0.3s;\n}\n#send-btn:hover {\n    background: #3182ce;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0101","card":"q-langchain-chatbot-021-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"Which CSS media query makes the chatbot responsive on mobile?","a":"<p><code>@media (max-width: 768px)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@media (max-width: 768px) {\n    .chatbot-container {\n        margin: 10px;\n        border-radius: 10px;\n    }\n    #chat-container {\n        height: 400px;\n        padding: 15px;\n    }\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0102","card":"q-langchain-chatbot-021-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"How do the message bubbles and the input row change on small screens?","a":"<p>Messages become 85% wide with 14px font. The input container switches to <code>flex-direction: column</code>, and the Send button becomes full width.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>.message {\n    max-width: 85%;\n    font-size: 14px;\n}\n.input-container {\n    padding: 15px;\n    flex-direction: column;\n}\n#send-btn {\n    margin-left: 0;\n    width: 100%;\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0103","card":"q-langchain-chatbot-021-10-1-better-styling-and-responsive-layou","sec":"langchain-chatbot-s019","q":"Why does the mobile input keep <code>font-size: 16px</code>?","a":"<p>It prevents zoom on iOS.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>#user-input {\n    margin-bottom: 10px;\n    font-size: 16px; /* Prevents zoom on iOS */\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0104","card":"q-langchain-chatbot-022-10-2-typing-indicator-error-message-ente","sec":"langchain-chatbot-s020","q":"How does the enhanced <code>sendMessage</code> show that the bot is working?","a":"<p>It displays the user message, calls <code>showTypingIndicator()</code>, then sends the message to the server.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>function sendMessage() {\n    const userMessage = userInput.value.trim();\n    if (userMessage) {\n        displayMessage(&#x27;user&#x27;, userMessage);\n        showTypingIndicator();\n        sendMessageToServer(userMessage);\n        userInput.value = &#x27;&#x27;;\n    }\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0105","card":"q-langchain-chatbot-022-10-2-typing-indicator-error-message-ente","sec":"langchain-chatbot-s020","q":"How do you implement the typing indicator in JavaScript?","a":"<p>Add a bot-styled div with the id <code>typing-indicator</code> and the text \"Mr. Landon is typing...\", then remove it when the response arrives.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>function showTypingIndicator() {\n    const typingDiv = document.createElement(&#x27;div&#x27;);\n    typingDiv.classList.add(&#x27;message&#x27;, &#x27;bot&#x27;, &#x27;typing&#x27;);\n    typingDiv.innerHTML = &#x27;Mr. Landon is typing...&#x27;;\n    typingDiv.id = &#x27;typing-indicator&#x27;;\n    chatContainer.appendChild(typingDiv);\n    chatContainer.scrollTop = chatContainer.scrollHeight;\n}\n\nfunction hideTypingIndicator() {\n    const typingIndicator = document.getElementById(&#x27;typing-indicator&#x27;);\n    if (typingIndicator) {\n        typingIndicator.remove();\n    }\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0106","card":"q-langchain-chatbot-022-10-2-typing-indicator-error-message-ente","sec":"langchain-chatbot-s020","q":"How does the enhanced <code>sendMessageToServer</code> handle a failed request?","a":"<p>It hides the typing indicator, shows the bot message \"Sorry, I encountered an error. Please try again.\" and logs the error to the console.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>.catch(error =&gt; {\n    hideTypingIndicator();\n    displayMessage(&#x27;bot&#x27;, &#x27;Sorry, I encountered an error. Please try again.&#x27;);\n    console.error(&#x27;Error:&#x27;, error);\n});</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0107","card":"q-langchain-chatbot-022-10-2-typing-indicator-error-message-ente","sec":"langchain-chatbot-s020","q":"How do you let the user send a message with the Enter key?","a":"<p>Add a <code>keypress</code> listener on the input and call <code>sendMessage()</code> when <code>e.key === 'Enter'</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>document.getElementById(&#x27;user-input&#x27;).addEventListener(&#x27;keypress&#x27;, function(e) {\n    if (e.key === &#x27;Enter&#x27;) {\n        sendMessage();\n    }\n});</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0108","card":"q-langchain-chatbot-023-10-3-memory-in-the-persona-chatbot","sec":"langchain-chatbot-s021","q":"How do you add chat history to the Mr. Landon persona chatbot?","a":"<p>Wrap a <code>ConversationBufferMemory</code> and a <code>ConversationChain</code> in an <code>EnhancedChatbot</code> class, and call it from the <code>/chatbot</code> route.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>self.memory = ConversationBufferMemory(\n    return_messages=True,\n    memory_key=&quot;chat_history&quot;\n)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0109","card":"q-langchain-chatbot-023-10-3-memory-in-the-persona-chatbot","sec":"langchain-chatbot-s021","q":"What does the memory-enabled persona template contain?","a":"<p>The extracted text, the persona instructions, the line \"Use the conversation history to provide contextual responses.\", the <code>{chat_history}</code> and the <code>{input}</code> placeholders, ending with <code>Mr. Landon:</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>template = f&quot;&quot;&quot;\n{prompt}\nYou are Mr. Landon, the hotel manager of Landon Hotel.\nUse the conversation history to provide contextual responses.\n\nCurrent conversation:\n{{chat_history}}\nHuman: {{input}}\nMr. Landon:&quot;&quot;&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0110","card":"q-langchain-chatbot-023-10-3-memory-in-the-persona-chatbot","sec":"langchain-chatbot-s021","q":"How do you build the <code>ConversationChain</code> of the persona chatbot and get a reply?","a":"<p>Pass the LLM, the memory and a <code>PromptTemplate</code> with the <code>chat_history</code> and <code>input</code> variables, then call <code>predict(input=...)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>self.chain = ConversationChain(\n    llm=OpenAI(temperature=0),\n    memory=self.memory,\n    prompt=PromptTemplate(\n        input_variables=[&quot;chat_history&quot;, &quot;input&quot;],\n        template=template\n    )\n)\n\ndef get_response(self, user_input):\n    return self.chain.predict(input=user_input)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0111","card":"q-langchain-chatbot-023-10-3-memory-in-the-persona-chatbot","sec":"langchain-chatbot-s021","q":"How does the Flask <code>/chatbot</code> route use the memory chatbot?","a":"<p>It creates one <code>EnhancedChatbot</code> and calls <code>get_response(question)</code> in the route.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>enhanced_chatbot = EnhancedChatbot()\n\n@app.route(&quot;/chatbot&quot;, methods=[&quot;POST&quot;])\ndef chatbot():\n    data = request.get_json()\n    question = data[&quot;question&quot;]\n    response = enhanced_chatbot.get_response(question)\n    return jsonify({&quot;response&quot;: response})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0112","card":"q-langchain-chatbot-024-10-4-multiple-sources-with-vector-search","sec":"langchain-chatbot-s022","q":"What is the multi-input chatbot approach with vector search and no chain?","a":"<p>Load the PDF and the website, split them, store them in FAISS, then run a manual <code>similarity_search</code> and build the prompt yourself.</p>","hand":true},{"id":"langchain-chatbot-f0113","card":"q-langchain-chatbot-024-10-4-multiple-sources-with-vector-search","sec":"langchain-chatbot-s022","q":"How does <code>MultiSourceChatbot</code> load the PDF and website content?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pdf_loader = PyPDFLoader(&quot;Landon-Hotel.pdf&quot;)\ndocuments.extend(pdf_loader.load())\n\nweb_loader = WebBaseLoader([&quot;https://www.landonhotel.com&quot;])\ndocuments.extend(web_loader.load())</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0114","card":"q-langchain-chatbot-024-10-4-multiple-sources-with-vector-search","sec":"langchain-chatbot-s022","q":"How does <code>MultiSourceChatbot</code> split the documents and create the vector store?","a":"<p>It splits with <code>split_documents</code> (1000 chunk size, 200 overlap) and builds the store with <code>FAISS.from_documents</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>splits = text_splitter.split_documents(documents)\n\nself.vectorstore = FAISS.from_documents(splits, self.embeddings)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0115","card":"q-langchain-chatbot-024-10-4-multiple-sources-with-vector-search","sec":"langchain-chatbot-s022","q":"How does <code>get_relevant_context</code> fetch context for a question?","a":"<p>It runs <code>similarity_search(question, k=k)</code> (default <code>k=3</code>) and joins the <code>page_content</code> of the hits, or returns an empty string without a vector store.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def get_relevant_context(self, question, k=3):\n    if self.vectorstore:\n        docs = self.vectorstore.similarity_search(question, k=k)\n        return &quot;\\n&quot;.join([doc.page_content for doc in docs])\n    return &quot;&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0116","card":"q-langchain-chatbot-024-10-4-multiple-sources-with-vector-search","sec":"langchain-chatbot-s022","q":"How does <code>generate_response</code> build its prompt in the no-chain approach?","a":"<p>It puts the retrieved context, the Mr. Landon persona, the instruction to answer from the context, and the refusal for off-topic questions into one f-string prompt.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>context = self.get_relevant_context(question)\nprompt = f&quot;&quot;&quot;\nContext: {context}\nYou are Mr. Landon, hotel manager of Landon Hotel.\nAnswer based on the context provided.\nIf the question is not about Landon Hotel, say &quot;I can&#x27;t assist you with that, sorry!&quot;\n\nQuestion: {question}\nAnswer:&quot;&quot;&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0117","card":"q-langchain-chatbot-025-10-5-sentiment-adaptive-tone","sec":"langchain-chatbot-s023","q":"How does <code>analyze_sentiment</code> classify user input?","a":"<p>It uses TextBlob polarity. Over 0.1 is <code>\"positive\"</code>, below -0.1 is <code>\"negative\"</code>, anything else is <code>\"neutral\"</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from textblob import TextBlob\n\ndef analyze_sentiment(text):\n    blob = TextBlob(text)\n    polarity = blob.sentiment.polarity\n    if polarity &gt; 0.1:\n        return &quot;positive&quot;\n    elif polarity &lt; -0.1:\n        return &quot;negative&quot;\n    else:\n        return &quot;neutral&quot;</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0118","card":"q-langchain-chatbot-025-10-5-sentiment-adaptive-tone","sec":"langchain-chatbot-s023","q":"How does <code>adapt_response_tone</code> change the reply for negative, positive and neutral sentiment?","a":"<p>Negative: it prefixes \"I understand your concern.\" and adds \"Is there anything else I can help you with?\". Positive: it appends \"I'm glad I could help!\". Neutral: the response stays unchanged.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def adapt_response_tone(response, sentiment):\n    if sentiment == &quot;negative&quot;:\n        return f&quot;I understand your concern. {response} Is there anything else I can help you with?&quot;\n    elif sentiment == &quot;positive&quot;:\n        return f&quot;{response} I&#x27;m glad I could help!&quot;\n    else:\n        return response</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0119","card":"q-langchain-chatbot-025-10-5-sentiment-adaptive-tone","sec":"langchain-chatbot-s023","q":"How does <code>enhanced_query_llm</code> combine sentiment and the chatbot answer?","a":"<p>It analyses the question's sentiment, gets the base answer from <code>query_llm</code>, then adapts its tone.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def enhanced_query_llm(question):\n    sentiment = analyze_sentiment(question)\n    base_response = query_llm(question)\n    adapted_response = adapt_response_tone(base_response, sentiment)\n    return adapted_response</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0120","card":"q-langchain-chatbot-026-10-6-real-time-chat-websocket","sec":"langchain-chatbot-s024","q":"Which library adds real-time WebSocket chat to the Flask chatbot?","a":"<p>Flask-SocketIO.</p>","hand":true},{"id":"langchain-chatbot-f0121","card":"q-langchain-chatbot-026-10-6-real-time-chat-websocket","sec":"langchain-chatbot-s024","q":"How does the Flask-SocketIO server handle a chat message?","a":"<p>It listens for a <code>message</code> event, calls <code>query_llm</code> on the question and emits a <code>response</code> event.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from flask_socketio import SocketIO, emit\n\nsocketio = SocketIO(app, cors_allowed_origins=&quot;*&quot;)\n\n@socketio.on(&#x27;message&#x27;)\ndef handle_message(data):\n    question = data[&#x27;question&#x27;]\n    response = query_llm(question)\n    emit(&#x27;response&#x27;, {&#x27;response&#x27;: response})</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0122","card":"q-langchain-chatbot-026-10-6-real-time-chat-websocket","sec":"langchain-chatbot-s024","q":"How does the browser client send and receive real-time chat messages?","a":"<p>It opens a socket with <code>io()</code>, emits <code>message</code> with the question, and shows the bot message when a <code>response</code> event arrives.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const socket = io();\n\nsocket.on(&#x27;response&#x27;, function(data) {\n    displayMessage(&#x27;bot&#x27;, data.response);\n});\n\nfunction sendMessageRealTime(message) {\n    socket.emit(&#x27;message&#x27;, {question: message});\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0123","card":"q-langchain-chatbot-027-10-7-usage-analytics","sec":"langchain-chatbot-s025","q":"What does the <code>ChatbotAnalytics</code> class track and where is it stored?","a":"<p>Total conversations and counts of common questions, in the JSON file <code>chatbot_analytics.json</code>.</p>","hand":true},{"id":"langchain-chatbot-f0124","card":"q-langchain-chatbot-027-10-7-usage-analytics","sec":"langchain-chatbot-s025","q":"How does <code>load_analytics</code> handle a missing analytics file?","a":"<p>It catches <code>FileNotFoundError</code> and starts with <code>total_conversations</code> 0, an empty <code>common_questions</code> dict and an empty <code>user_satisfaction</code> list.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def load_analytics(self):\n    try:\n        with open(self.analytics_file, &#x27;r&#x27;) as f:\n            self.data = json.load(f)\n    except FileNotFoundError:\n        self.data = {\n            &quot;total_conversations&quot;: 0,\n            &quot;common_questions&quot;: {},\n            &quot;user_satisfaction&quot;: []\n        }</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0125","card":"q-langchain-chatbot-027-10-7-usage-analytics","sec":"langchain-chatbot-s025","q":"How does <code>log_interaction</code> record a question?","a":"<p>It increments the total, increments the question's count (or sets it to 1), and writes the data to the JSON file.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>self.data[&quot;total_conversations&quot;] += 1\n\nif question in self.data[&quot;common_questions&quot;]:\n    self.data[&quot;common_questions&quot;][question] += 1\nelse:\n    self.data[&quot;common_questions&quot;][question] = 1\n\nwith open(self.analytics_file, &#x27;w&#x27;) as f:\n    json.dump(self.data, f, indent=2)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0126","card":"q-langchain-chatbot-027-10-7-usage-analytics","sec":"langchain-chatbot-s025","q":"What does <code>get_analytics_summary</code> return?","a":"<p>The total conversations and the top 5 questions, sorted by count in descending order.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>return {\n    &quot;total_conversations&quot;: self.data[&quot;total_conversations&quot;],\n    &quot;top_questions&quot;: sorted(\n        self.data[&quot;common_questions&quot;].items(),\n        key=lambda x: x[1],\n        reverse=True\n    )[:5]\n}</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0127","card":"q-langchain-chatbot-027-10-7-usage-analytics","sec":"langchain-chatbot-s025","q":"How do you log analytics with response time in the Flask <code>/chatbot</code> route?","a":"<p>Take <code>time.time()</code> before the call, compute the elapsed time after <code>query_llm</code>, and call <code>analytics.log_interaction</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>start_time = time.time()\nresponse = query_llm(question)\nresponse_time = time.time() - start_time\n\nanalytics.log_interaction(question, response, response_time)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0128","card":"q-langchain-chatbot-028-10-8-production-configuration-config-cla","sec":"langchain-chatbot-s026","q":"How do you structure Flask settings with config classes?","a":"<p>A base <code>Config</code> reads <code>SECRET_KEY</code> (with a dev fallback) and <code>OPENAI_API_KEY</code> from the environment. <code>ProductionConfig</code> sets <code>DEBUG = False</code> and <code>DevelopmentConfig</code> sets <code>DEBUG = True</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>class Config:\n    SECRET_KEY = os.environ.get(&#x27;SECRET_KEY&#x27;) or &#x27;dev-secret-key&#x27;\n    OPENAI_API_KEY = os.environ.get(&#x27;OPENAI_API_KEY&#x27;)\n\nclass ProductionConfig(Config):\n    DEBUG = False\n\nclass DevelopmentConfig(Config):\n    DEBUG = True</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0129","card":"q-langchain-chatbot-028-10-8-production-configuration-config-cla","sec":"langchain-chatbot-s026","q":"What is the app factory pattern in the Flask chatbot?","a":"<p>A <code>create_app(config_class=DevelopmentConfig)</code> function that creates the Flask app, loads the config with <code>app.config.from_object</code>, initialises extensions, registers blueprints and returns the app.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def create_app(config_class=DevelopmentConfig):\n    app = Flask(__name__)\n    app.config.from_object(config_class)\n    return app</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0130","card":"q-langchain-chatbot-028-10-8-production-configuration-config-cla","sec":"langchain-chatbot-s026","q":"How do you start the app with the production config?","a":"<p>Call <code>create_app(ProductionConfig)</code> and run it on host <code>0.0.0.0</code>, port 5000.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if __name__ == &#x27;__main__&#x27;:\n    app = create_app(ProductionConfig)\n    app.run(host=&#x27;0.0.0.0&#x27;, port=5000)</code></pre></div>","hand":true},{"id":"langchain-chatbot-f0131","card":"q-langchain-chatbot-029-11-next-steps-and-deployment-options","sec":"langchain-chatbot-s027","q":"What hygiene practices does the chatbot course recommend?","a":"<p>Keep the key in environment variables, use try/except around file, network and API calls, validate data, use UTF-8, clear memory when needed, and consider a database for large document sets.</p>","hand":true},{"id":"langchain-chatbot-f0132","card":"q-langchain-chatbot-029-11-next-steps-and-deployment-options","sec":"langchain-chatbot-s027","q":"Which LangChain chains should you study next?","a":"<p><code>ConversationalRetrievalChain</code>, <code>RetrievalQA</code> and <code>LLMChain</code> with custom prompts.</p>","hand":true},{"id":"langchain-chatbot-f0133","card":"q-langchain-chatbot-029-11-next-steps-and-deployment-options","sec":"langchain-chatbot-s027","q":"Which LangChain memory types should you study next?","a":"<p><code>ConversationBufferMemory</code>, <code>ConversationSummaryMemory</code> and <code>VectorStoreRetrieverMemory</code>.</p>","hand":true},{"id":"langchain-chatbot-f0134","card":"q-langchain-chatbot-029-11-next-steps-and-deployment-options","sec":"langchain-chatbot-s027","q":"Which LangChain agents and retrievers should you study next?","a":"<p>Agents: ReAct agents, tool-using agents and custom agents. Retrievers: vector store, web search and multi-query retrievers.</p>","hand":true},{"id":"langchain-chatbot-f0135","card":"q-langchain-chatbot-029-11-next-steps-and-deployment-options","sec":"langchain-chatbot-s027","q":"Which deployment options does the chatbot course list?","a":"<p>Heroku (simple), AWS/GCP (scalable), Docker (containers), and Vercel/Netlify (front end with serverless back end).</p>","hand":true}];
